212	\section{Consistency with the points measurements}
213	
214	The next lemma shows that the pulled-apart measurements are consistent with the original points measurements of the strategy, and self-consistent. Write $\delta_G$ for the error of the global polynomial-pair witness supplied by Lemma~\ref{lem:qld-4-7}. Assume $0\leq\eps\leq1$ and $\delta_G\geq0$, and put
215	\[
216		B = \delta_G + \sqrt{\eps} + \frac{md}{q}.
217	\]
218	Each displayed construction estimate below has its own universal constant $C_E \geq 1$, quantified independently, and its own scale $\delta_P^E=C_EB$. The source uses one enlarged error $\delta_S$ for all of these estimates. The two presentations agree: after the finitely many estimates have been established, take $C_* = \max_E C_E$ and $\delta_P=C_*B$. Since $B\geq0$, every bound remains valid at this common scale. In the proof paragraphs, $\delta_P$ denotes this common enlargement. It has the same asymptotic form as $\delta_G$: after shrinking $b$ to at most $1/2$, the term $\eps^b$ dominates $\sqrt{\eps}$ for $0 \leq \eps \leq 1$, while $(md)^a q^{-b}$ dominates $md/q$.
219	
220	\begin{lemma}[Consistency and self-consistency of the pulled-apart measurements]\label{lem:qld-construct-the-paulis}
221		\lean{MIPStarRE.QPBT.deltaConstructPaulis}
222		\uses{def:tilde-m-measurement, def:tilde-w-observables,
223			lem:projective-strategy-setup, def:expanded-state, def:consistency,
224			def:approx-question-indexed-operators, lem:qld-4-7,
225			def:indicator-vector}
226		The measurements $\{\tilde{M}^{W,\tilde{u}}_a\}_{a \in \F_q}$ and observables $\tilde{W}^j(\tilde{u})$ satisfy the following properties.
227		% The paper's statement also quantifies item 1 over j, but j does not occur
228		% in item 1; the vacuous quantifier is dropped here.
229		\begin{enumerate}
230			\item (\textbf{Consistency with points measurements}) For all $W \in \{X,Z\}$, on average over uniformly random $u \in \F_q^m$,
231			\[
232				\Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \simeq_{\delta_P^{\mathrm{AB}}} M^{(\mathrm{Point},W),u}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''}
233			\]
234			and
235			\[
236				\tilde{M}^{W,\mathrm{ind}_m(u)}_a \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \simeq_{\delta_P^{\mathrm{BA}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot M^{(\mathrm{Point},W),u}_a\;,
237			\]
238			with the answer summation over $a \in \F_q$.
239			\item (\textbf{Self-consistency}) For all $W \in \{X,Z\}$ and $j \in \{0,\ldots,t-1\}$, on average over uniformly random $\tilde{u} \in \F_q^{M}$,
240			\[
241				\tilde{W}^j(\tilde{u}) \ot \Id_{\mathrm{B}\mathrm{B}'\mathrm{B}''} \approx_{\delta_P^{\mathrm{obs}}} \Id_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \ot \tilde{W}^j(\tilde{u})\;.
242			\]
243		\end{enumerate}
244	\end{lemma}
245	\begin{proof}
246		\uses{lem:qld-4-7, lem:qld-constructing-the-paulis-helper, def:expanded-point-measurement, def:tilde-m-measurement, def:tau-dot-product-projector, lem:qld-decoder-evaluation, lem:qld-decoder-linearity, def:indicator-vector, lem:qld-win-implications, lem:qld-comm-cons, fact:add-a-proj, fact:agreement, fact:triangle, fact:data-processing, def:bracket, lem:povm-to-obs, lem:schwartz-zippel-total-degree}
247		% Support restriction added: the source (line 1492 of
248		% 14_analysis_of_the_pauli_basis_test.tex) rewrites Dec(g).ind_m(u) as
249		% g(u) for every outcome g; see Remark rem:qld-decoding-identity.
250		We first bound the mass that the marginal measurements $\{\hat{S}^W_g\}$ place on polynomials that are not encodings. On average over uniformly random $u \in \F_q^m$, the point-consistency relation \eqref{eq:qld-s-point-con-bob} of Lemma~\ref{lem:qld-4-7} gives $(\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \approx_{\delta_G} (\hat{M}^{(\mathrm{Point},W),u}_a)_{\mathrm{A}\mathrm{B}''}$ (Lemma~\ref{fact:agreement}); the consistency and Pauli-basis-consistency checks of Lemma~\ref{lem:qld-win-implications} give, again on average over uniform $u$ and combining through Lemma~\ref{fact:data-processing}, Lemma~\ref{fact:agreement}, and Lemma~\ref{fact:triangle}, that $(M^{(\mathrm{Point},W),u}_{a'})_{\mathrm{A}} \approx_{O(\eps)} (M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']})_{\mathrm{A}}$; and replacing the point factor of the convolution form of $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) accordingly costs the same error, because the projectors $\tau^W_{a''}(\mathrm{ind}_m(u))$ of \eqref{eq:def-tauwu} are mutually orthogonal (Lemma~\ref{fact:add-a-proj}). Writing
251		\[
252			K^u_a = \sum_{a' + a'' = a} \bigl(M^{(\mathrm{Pauli},W)}_{[g_h(u)=a']}\bigr)_{\mathrm{A}} \ot \bigl(\tau^W_{a''}(\mathrm{ind}_m(u))\bigr)_{\mathrm{B}''}\;,
253		\]
254		a projective measurement, Lemma~\ref{fact:triangle} and Lemma~\ref{fact:agreement} therefore give
255		\[
256			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} (\hat{S}^W_{[g(u)=a]})_{\mathrm{B}\mathrm{B}'} \ot (K^u_a)_{\mathrm{A}\mathrm{B}''} \ket{\hat\psi} \geq 1 - O(\delta_G + \eps)\;.
257		\]
258		Expanding $K^u_a$ over pairs $(h, h'')$ of Pauli outcomes, a term of the left-hand side with outcomes $(g, h, h'')$ is constrained by $g(u) = g_h(u) + g_{h''}(u) = g_{h + h''}(u)$, by the linearity of the encoding \eqref{eq:low-degree-encoding-definition}. If $g$ is not an encoding then $g \neq g_{h+h''}$, and both are polynomials of total degree at most $md$, so the constraint holds for at most an $md/q$ fraction of $u$ (Lemma~\ref{lem:schwartz-zippel-total-degree}). Since all terms are nonnegative and, for each $g$, the operators of the $(h,h'')$-sum add up to the identity, it follows that
259		\begin{equation}\label{eq:qld-nonencoding-mass}
260		\sum_{g \,\text{not an encoding}} \bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} \,\leq\, O(\delta_G + \eps) + \frac{md}{q} \,\leq\, \delta_P\;,
261		\end{equation}
262		and symmetrically with the registers $\mathrm{A}\mathrm{A}'$ in place of $\mathrm{B}\mathrm{B}'$. (If $d = 0$, every element of $\mathrm{ideg}_{d,m}(\F_q)$ is constant, hence an encoding, and the left-hand side vanishes.)
263	
264		For the first item, in the case where $M^{(\mathrm{Point},W),u}_a$ acts on register $\mathrm{A}$ and $\tilde{M}^{W,\mathrm{ind}_m(u)}_a$ on $\mathrm{B}\mathrm{B}'\mathrm{B}''$, expanding \eqref{eq:tilde_M} and \eqref{eq:def-tauwu} and using the convolution form of the combined projectors $\hat{M}^{(\mathrm{Point},W),u}_a$ (Definition~\ref{def:expanded-point-measurement}) gives the exact identity
265		\[
266			\E_{u \in \F_q^m} \sum_a \bra{\hat\psi} M^{(\mathrm{Point},W),u}_a \ot \tilde{M}^{W,\mathrm{ind}_m(u)}_a \ket{\hat\psi}
267			= \E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}\;.
268		\]
269		For encodings $g$ the subscript $\mathrm{Dec}(g) \cdot \mathrm{ind}_m(u)$ equals $g(u)$; discarding the (nonnegative) terms with $g$ not an encoding and reinstating the corresponding terms with subscript $g(u)$, each of which is at most $\bra{\hat\psi} (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi}$, shows that the right-hand side is at least
270		\[
271			\E_{u \in \F_q^m} \sum_g \bra{\hat\psi} (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{A}\mathrm{B}''} \ot (\hat{S}^W_g)_{\mathrm{B}\mathrm{B}'} \ket{\hat\psi} - \delta_P
272			\geq 1 - \delta_P
273		\]
274		by \eqref{eq:qld-nonencoding-mass} and Lemma~\ref{lem:qld-4-7}, and the register-interchanged relation follows analogously. For the second item one first shows that, on average over uniformly random $\tilde{u} \in \F_q^M$,
275		\begin{equation}\label{eq:qld-pulling-cons}
276			\bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_P} \bigl( \tilde{M}^{W,\tilde{u}}_a \bigr)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}\;:
277		\end{equation}
278		right-multiplying by the resolution $\sum_g (\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\hat{M}^{(\mathrm{Point},W),u}_{g(u)})_{\mathrm{B}\mathrm{A}''} \approx_{\delta_P} \Id$ of Lemma~\ref{lem:qld-constructing-the-paulis-helper} (with Lemma~\ref{fact:add-a-proj}) and expanding the products of $\tau^W$ projectors via \eqref{eq:def-tauwu} and $h \cdot \mathrm{ind}_m(u) = g_h(u)$ places $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{A}\mathrm{A}'\mathrm{A}''}$ within $O(\delta_P)$ of a sum over pairs $(g,h)$ with $(\mathrm{Dec}(g)-h)\cdot\tilde{u} = a$. One then applies, in turn, the self-consistency of the points measurements (Lemma~\ref{lem:qld-win-implications}) at cost $\eps$; the exact identity $\ket{\hat\psi} = \sum_{h'} (\tau^W_{h'})_{\mathrm{B}'} \ot (\tau^W_{h'})_{\mathrm{B}''} \ket{\hat\psi}$ of the EPR registers; Lemma~\ref{lem:qld-constructing-the-paulis-helper} twice more (once through a Cauchy--Schwarz detour of cost $O(\sqrt{\eps})$ using the self-consistency of the $\hat{M}^{(\mathrm{Point},W),u}_a$, Lemma~\ref{lem:qld-comm-cons}); and finally a Schwartz--Zippel step (Lemma~\ref{lem:schwartz-zippel-total-degree}, for polynomials of total degree at most $md$) which replaces the event $(g'-g_{h'})(u) = (g-g_h)(u)$ by the polynomial identity $g'-g_{h'} = g-g_h$ at cost $md/q$. The resulting expression
279		\[
280			\sum_{\substack{g,h,g',h': \\ g' - g_{h'} = g - g_h \\ (\mathrm{Dec}(g)-h)\cdot \tilde{u} = a}}
281			\Bigl((\hat{S}^W_g)_{\mathrm{A}\mathrm{A}'} \ot (\tau_h^W)_{\mathrm{A}''} \Bigr) \cdot \Bigl( (\hat{S}^W_{g'})_{\mathrm{B}\mathrm{B}'} \ot (\tau_{h'}^W)_{\mathrm{B}''} \Bigr)
282		\]
283		is symmetric under exchanging $(g,h)$ with $(g',h')$: since $\mathrm{Dec}$ is linear with $\mathrm{Dec}(g_{h}) = h$ for all $h \in \F_q^M$ (Remark~\ref{rem:qld-decoding-identity}), the constraint $g' - g_{h'} = g - g_h$ implies $\mathrm{Dec}(g) - h = \mathrm{Dec}(g') - h'$, so the two constraint sets coincide. The same derivation therefore bounds the distance of the displayed expression to $(\tilde{M}^{W,\tilde{u}}_a)_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$, and \eqref{eq:qld-pulling-cons} follows at the common scale $\delta_P$. Finally, since $\{\tilde{M}^{W,\tilde{u}}_a\}$ is projective, Item~2 of Lemma~\ref{fact:agreement}, data processing along the map $a \mapsto \tr(e_j a)$ (Lemma~\ref{fact:data-processing}), and Item~1 of Lemma~\ref{fact:agreement} yield $(\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{A}\mathrm{A}'\mathrm{A}''} \approx_{\delta_P} (\tilde{M}^{W,\tilde{u}}_{[\tr(e_j \cdot) = b]})_{\mathrm{B}\mathrm{B}'\mathrm{B}''}$ with answer summation over $b \in \F_2$, and Lemma~\ref{lem:povm-to-obs} converts this into the claimed self-consistency of the observables $\tilde{W}^j(\tilde{u})$.
284	\end{proof}
285	
286	\begin{lemma}[Non-encoding support estimate]
287	\label{lem:qld-nonencoding-mass-bound}
288		\lean{MIPStarRE.QPBT.nonencodingMarginalMass}
289		\lean{MIPStarRE.QPBT.nonencodingMarginalMass_le}
290		\uses{def:s-w-marginals, def:qld-full-field-decoder, def:expanded-state,
291			lem:qld-4-7}
292		For either player and either Pauli basis, the non-encoding marginal mass in
293		Equation~\eqref{eq:qld-nonencoding-mass} is at most
294		$\delta_P^{\mathrm{supp}}=C_{\mathrm{supp}}B$ for a universal
295		$C_{\mathrm{supp}}\geq1$. This bound must be derived from point consistency and
296		Schwartz--Zippel; it is not an additional extraction hypothesis.
