353	\begin{lemma}[Unitarity and conjugation action of the swap unitaries]\label{lem:v-swap-conjugation}
354		\lean{MIPStarRE.QPBT.swapUnitary_mul_conjTranspose}
355		\lean{MIPStarRE.QPBT.conjTranspose_mul_swapUnitary}
356		\lean{MIPStarRE.QPBT.swapUnitary_conj_tildeObs}
